export async function registerOffline(){if(!('serviceWorker'in navigator))return null;try{return await navigator.serviceWorker.register('./sw.js');}catch{return null;}}
export async function downloadOffline(sex,onProgress){const registration=await registerOffline();if(!registration)throw Error('Bu tarayıcı çevrimdışı kaydı desteklemiyor.');await navigator.serviceWorker.ready;const worker=registration.active||navigator.serviceWorker.controller;if(!worker)throw Error('Sayfayı bir kez yenileyip tekrar dene.');return new Promise((resolve,reject)=>{const channel=new MessageChannel();channel.port1.onmessage=e=>{const d=e.data;if(d.type==='progress')onProgress(d.done,d.total);if(d.type==='done'){channel.port1.close();resolve(d);}if(d.type==='error'){channel.port1.close();reject(Error(d.message));}};worker.postMessage({type:'download',sex},[channel.port2]);});}
